pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address owner1, address owner2) public {
        vm.assume(owner1 != owner2);

        vm.prank(address(this));
        c.setOwner(owner1);

        vm.prank(address(this));
        c.setOwner(owner2);

        assertTrue(c.owner() == owner2);
    }
}
